// Package pbwire is the wire-format runtime for code generated by
// protoc-gen-pbwire-go: varint, fixed-width and length-delimited primitives
// plus the tag/unknown-field scanner. It has no dependencies and no state; the
// generated code owns the message types and calls these helpers in straight
// line.
//
// Decode treats the bytes as untrusted: every length is bounds-checked, field
// number 0 and wire types above 5 are rejected, and group skipping is capped
// at MaxDepth. Unknown fields are skipped, not preserved: a generated struct
// has no storage for them (the dynamic core and the C struct engine behave the
// same way).
package pbwire

import "errors"

// MaxDepth caps nesting in both directions, like the C core (PBW_MAX_DEPTH).
const MaxDepth = 256

var (
	// ErrWire reports malformed wire bytes: a truncated varint or length, a
	// zero field number, an unknown wire type or an unmatched group.
	ErrWire = errors.New("pbwire: malformed wire data")
	// ErrDepth reports nesting at or past MaxDepth.
	ErrDepth = errors.New("pbwire: nesting exceeds MaxDepth")
	// ErrRequired reports a proto2 required field that was neither encoded nor
	// present on the wire.
	ErrRequired = errors.New("pbwire: required field missing")
)

// AppendVarint appends v in base-128 varint form.
func AppendVarint(b []byte, v uint64) []byte {
	for v >= 0x80 {
		b = append(b, byte(v)|0x80)
		v >>= 7
	}
	return append(b, byte(v))
}

// AppendFixed32 appends v little-endian.
func AppendFixed32(b []byte, v uint32) []byte {
	return append(b, byte(v), byte(v>>8), byte(v>>16), byte(v>>24))
}

// AppendFixed64 appends v little-endian.
func AppendFixed64(b []byte, v uint64) []byte {
	return append(b, byte(v), byte(v>>8), byte(v>>16), byte(v>>24),
		byte(v>>32), byte(v>>40), byte(v>>48), byte(v>>56))
}

// AppendBool appends a bool as a varint, the way the wire format wants it.
func AppendBool(b []byte, v bool) []byte {
	if v {
		return append(b, 1)
	}
	return append(b, 0)
}

// AppendString appends a length-delimited payload.
func AppendString(b []byte, s string) []byte {
	b = AppendVarint(b, uint64(len(s)))
	return append(b, s...)
}

// AppendBytes appends a length-delimited payload.
func AppendBytes(b []byte, p []byte) []byte {
	b = AppendVarint(b, uint64(len(p)))
	return append(b, p...)
}

// FinishSlice writes the length of the payload that starts after the one-byte
// placeholder at mark. The payload moves right when the length itself needs
// more than one byte; only callers that reserved the placeholder (see
// generated code) use it.
func FinishSlice(b []byte, mark int) []byte {
	n := len(b) - mark - 1
	if n < 0x80 {
		b[mark] = byte(n)
		return b
	}
	var tmp [5]byte
	w := putVarint(tmp[:], uint64(n))
	b = append(b, tmp[1:w]...)
	copy(b[mark+w:], b[mark+1:])
	copy(b[mark:], tmp[:w])
	return b
}

// VarintSize reports the encoded width of v without encoding it.
func VarintSize(v uint64) int {
	n := 1
	for v >= 0x80 {
		v >>= 7
		n++
	}
	return n
}

func putVarint(b []byte, v uint64) int {
	i := 0
	for v >= 0x80 {
		b[i] = byte(v) | 0x80
		v >>= 7
		i++
	}
	b[i] = byte(v)
	return i + 1
}

// ConsumeVarint reads a varint and returns its value with the number of bytes
// consumed, or -1 when the input is truncated or wider than 64 bits.
func ConsumeVarint(b []byte) (uint64, int) {
	var v uint64
	for i := 0; i < len(b) && i < 10; i++ {
		c := b[i]
		v |= uint64(c&0x7f) << (7 * i)
		if c < 0x80 {
			return v, i + 1
		}
	}
	return 0, -1
}

// ConsumeFixed32 reads a little-endian uint32.
func ConsumeFixed32(b []byte) (uint32, int) {
	if len(b) < 4 {
		return 0, -1
	}
	return uint32(b[0]) | uint32(b[1])<<8 | uint32(b[2])<<16 | uint32(b[3])<<24, 4
}

// ConsumeFixed64 reads a little-endian uint64.
func ConsumeFixed64(b []byte) (uint64, int) {
	if len(b) < 8 {
		return 0, -1
	}
	return uint64(b[0]) | uint64(b[1])<<8 | uint64(b[2])<<16 | uint64(b[3])<<24 |
		uint64(b[4])<<32 | uint64(b[5])<<40 | uint64(b[6])<<48 | uint64(b[7])<<56, 8
}

// ConsumeBytes reads a length-delimited payload and returns it as a subslice of
// b. Callers that store it must copy.
func ConsumeBytes(b []byte) ([]byte, int) {
	n, k := ConsumeVarint(b)
	if k < 0 || n > uint64(len(b)-k) {
		return nil, -1
	}
	end := k + int(n)
	return b[k:end], end
}

// ConsumeTag reads a field tag. The field number is rejected when it is zero or
// above 2^29, and wire types 6 and 7 do not exist.
func ConsumeTag(b []byte) (num uint32, wt uint8, n int) {
	v, n := ConsumeVarint(b)
	if n < 0 {
		return 0, 0, -1
	}
	num = uint32(v >> 3)
	wt = uint8(v & 7)
	if num == 0 || v>>3 > 0x1fffffff || wt > 5 {
		return 0, 0, -1
	}
	return num, wt, n
}

// SkipField skips one field value of wire type wt. num is the field number the
// tag carried, needed to match an end-group tag. It returns the number of bytes
// consumed or -1 when the value is truncated, the group is unterminated or
// groups nest past MaxDepth.
func SkipField(b []byte, num uint32, wt uint8, depth int) int {
	switch wt {
	case 0:
		_, n := ConsumeVarint(b)
		return n
	case 1:
		if len(b) < 8 {
			return -1
		}
		return 8
	case 2:
		_, n := ConsumeBytes(b)
		return n
	case 3:
		if depth >= MaxDepth {
			return -1
		}
		off := 0
		for {
			inner, innerWT, n := ConsumeTag(b[off:])
			if n < 0 {
				return -1
			}
			off += n
			if innerWT == 4 {
				if inner != num {
					return -1
				}
				return off
			}
			n = SkipField(b[off:], inner, innerWT, depth+1)
			if n < 0 {
				return -1
			}
			off += n
		}
	case 5:
		if len(b) < 4 {
			return -1
		}
		return 4
	}
	return -1
}
